actions.script:
import org.moqui.adk.AdkManager
if (!AdkManager.isInitialized()) { AdkManager.lazyInit(ec.factory) } if (!AdkManager.isInitialized()) { ec.logger.warn("ADK not initialized — skipping scheduled run for ${cfg.agentName}") return }
String prompt = cfg.schedulePrompt ?: 'Perform your scheduled task.'
// Create a one-off session for this scheduled run Map sessionCtx = [ userId : 'scheduler', username : 'scheduler', userFullName : 'Scheduler', organizationName: '', companyPseudoId : '', tenantId : cfg.ownerPartyId ?: 'DEFAULT', timeZone : 'UTC', locale : 'en_US', ] Map session = AdkManager.createSession('scheduler', sessionCtx) String sessionId = session.id as String
// Run the agent synchronously List events = AdkManager.runAgent('scheduler', sessionId, prompt) def textEvent = events.reverse().find { e -> e.author == 'model' && e.content?.parts?.find { it.text } } String result = textEvent?.content?.parts?.find { it.text }?.text ?: '[No response]'
agentName = cfg.agentName ?: 'ADK Agent' chatRoomId = cfg.scheduleChatRoomId as String resultText = "[${agentName}] ${result}"

if.script:
// Find the ownerPartyId's primary user to post as
String fromUserId = null
try {
    boolean wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        if (cfg.ownerPartyId) {
            def memberList = ec.entity.find('growerp.general.ChatRoomMember')
                .condition('chatRoomId', chatRoomId).limit(1).list()
            if (memberList) fromUserId = memberList[0].userId as String
        }
        if (!fromUserId) {
            def sysUser = ec.entity.find('moqui.security.UserAccount')
                .condition('username', 'SystemSupport').one()
            fromUserId = sysUser?.userId as String
        }
    } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
} catch (Exception ignored) {}
